import bpy, os, json
from mathutils import Vector
from mathutils.bvhtree import BVHTree
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout'); tower=bpy.data.objects.get('V4 | torre documental'); hall=bpy.data.objects.get('V4 | hall piso terreo marcador'); staging=bpy.data.collections.get('02 ENTORNO | OSM e patamares'); elev=bpy.data.collections.get('01 WORLD | ELEVADOR LACERDA | blockout v4')
if not all((terrain,tower,hall,staging,elev)): raise RuntimeError('base incompleta')
verts=[terrain.matrix_world@v.co for v in terrain.data.vertices]; polys=[tuple(p.vertices) for p in terrain.data.polygons]; bvh=BVHTree.FromPolygons(verts,polys,all_triangles=False)
def rayz(x,y):
 h=bvh.ray_cast(Vector((x,y,250)),Vector((0,0,-1)),600); return None if h[0] is None else float(h[0].z)
def bounds(o):
 ps=[o.matrix_world@Vector(c) for c in o.bound_box]; return min(p.z for p in ps),max(p.z for p in ps)
T=tower.matrix_world.translation.xy.copy(); H=hall.matrix_world.translation.xy.copy(); EX=(H-T).normalized(); EY=Vector((-EX.y,EX.x))
def sl(xy):
 r=xy-T; return float(r.dot(EX)),float(r.dot(EY))
def objrow(o):
 p=o.matrix_world.translation; s,l=sl(p.xy); a,b=bounds(o) if hasattr(o,'bound_box') else (p.z,p.z); tz=rayz(p.x,p.y); props={k:o[k] for k in o.keys()}; return {'name':o.name,'type':o.type,'s':round(s,3),'l':round(l,3),'loc':[round(p.x,3),round(p.y,3),round(p.z,3)],'zmin':round(a,3),'zmax':round(b,3),'terrain_z_at_origin':None if tz is None else round(tz,3),'collections':[c.name for c in o.users_collection],'props':props}
# Upper shell objects
upper=[]
for o in elev.objects:
 n=o.name.lower()
 if any(k in n for k in ('estacao','estação','hall','passadico','entrada','marquise','laje','piso','parede')) and o.type in {'MESH','CURVE','FONT','EMPTY'}:
  upper.append(objrow(o))
upper=sorted(upper,key=lambda r:(r['s'],r['l'],r['name']))
# Nearby staging objects around hall, with emphasis on named urban context
near=[]; named=[]
keywords=('praça','praca','tomé','tome','municipal','chile','rio branco','câmara','camara','prefeitura','palácio','palacio','misericordia','ajuda','sé','se','rua','ladeira')
for o in staging.objects:
 p=o.matrix_world.translation.xy; d=(p-H).length
 if d<=100 and o.type in {'MESH','CURVE','FONT','EMPTY'}:
  r=objrow(o); r['dist_to_hall_xy']=round(float(d),3); near.append(r)
  if any(k in o.name.lower() for k in keywords) or any(k in str({x:o[x] for x in o.keys()}).lower() for k in keywords): named.append(r)
near=sorted(near,key=lambda r:r['dist_to_hall_xy'])[:120]
named=sorted(named,key=lambda r:r['dist_to_hall_xy'])[:120]
# Terrain grid around upper hall in axis coordinates
grid=[]
for s in range(35,86,5):
 row=[]
 for l in range(-30,31,5):
  p=T+EX*s+EY*l; z=rayz(p.x,p.y); row.append({'l':l,'z':None if z is None else round(z,3)})
 grid.append({'s':s,'samples':row})
# Find terrain points near current upper floor elevation and common high plateau around shell
current_floor=bpy.data.objects.get('V4 | estacao laje 0'); floor_z=bounds(current_floor)[0] if current_floor else None
best=[]
if floor_z is not None:
 for s in [35+i*.5 for i in range(101)]:
  for l in [(-30+i) for i in range(61)]:
   p=T+EX*s+EY*l; z=rayz(p.x,p.y)
   if z is not None: best.append((abs(z-floor_z),s,l,z))
 best=sorted(best)[:20]
 best=[{'error':round(e,3),'s':round(s,3),'l':round(l,3),'terrain_z':round(z,3)} for e,s,l,z in best]
print('UPPER_ACCESS_CONTEXT_BEGIN')
print(json.dumps({'hall':objrow(hall),'upper_floor_z':None if floor_z is None else round(floor_z,3),'upper_shell':upper,'named_context':named,'nearest_context':near,'terrain_grid':grid,'terrain_near_current_floor_z':best},ensure_ascii=False,separators=(',',':'),default=str))
print('UPPER_ACCESS_CONTEXT_END')
